 "content": "def transform(grid):
    """Keep the pattern above the horizontal divider, recoloring its marks to 2
    unless the aligned cell below the divider is zero."""
    divider = next(i for i, row in enumerate(grid) if row and len(set(row)) == 1 and row[0] != 0)
    upper = grid[:divider]
    lower = grid[divider + 1:]
    out = []
    for r, row in enumerate(upper):
        new_row = []
        for c, value in enumerate(row):
            if value != 0 and r < len(lower) and c < len(lower[r]) and lower[r][c] == 0:
                new_row.append(0)
            elif value != 0:
                new_row.append(2)
            else:
                new_row.append(0)
        out.append(new_row)
    return out
